SELECT 'FactoryColor' AS source, code AS value, count(*) FROM "FactoryColor" GROUP BY 1,2 UNION ALL SELECT 'InventoryFinish.code', code, count(*) FROM "InventoryFinish" GROUP BY 1,2 UNION ALL SELECT 'MrpBatchUnit.colour', colour, count(*) FROM "MrpBatchUnit" GROUP BY 1,2 UNION ALL SELECT 'FactoryPlanningBooth.colorCode', "colorCode", count(*) FROM "FactoryPlanningBooth" GROUP BY 1,2 UNION ALL SELECT 'MrpElementBomLine.colour', colour, count(*) FROM "MrpElementBomLine" GROUP BY 1,2 UNION ALL SELECT 'BoothUnit.finish', finish::text, count(*) FROM "BoothUnit" GROUP BY 1,2 ORDER BY 1,3 DESC
